// Block (composition) — an iOS-style action sheet rising from the bottom edge.
// Contract: docs/rules/block-contract.md. Drawer owns open/close/focus/scrim;
// this Block arranges the action list. Self-contained overlay; mints no tokens.
import type { ReactNode } from "react";
import { Button } from "../components/Button";
import { DrawerContent, DrawerHeader, DrawerTitle, DrawerTrigger } from "../components/Drawer";
import { Stack } from "../layouts/Stack";
import "./ActionSheet.css";

export interface ActionSheetAction {
  /** Action label. */
  label: string;
  /** Called when the action is chosen (the sheet also closes). */
  onPress?: () => void;
  /** Renders the action with the destructive Button variant (e.g. Delete). */
  isDestructive?: boolean;
}

export interface ActionSheetProps {
  /** Control that opens the sheet. */
  trigger: ReactNode;
  /** Actions listed in the sheet. */
  actions: ActionSheetAction[];
  /** Sheet heading. **Required** — it is the drawer's accessible name (WCAG 4.1.2). */
  title: string;
  /** Dismiss label. */
  cancelLabel?: string;
  /** What the actions act on, shown above them (a link card, the photo being shared). Optional;
   *  the sheet is the list alone without it. */
  preview?: ReactNode;
}

export function ActionSheet({
  trigger,
  actions,
  title,
  cancelLabel = "Cancel",
  preview,
}: ActionSheetProps) {
  const list = (
    // A list of alternatives read top to bottom with Cancel last, so a plain Stack at the
    // action-row rung (`x-small`, the `button-group.gap` value). NOT a ButtonGroup: its `stack`
    // layout is column-reverse, a footer's order that puts the forward action on top, which here
    // moved Cancel to the top and parted the visual order from the focus order.
    <Stack gap="x-small" className="sd-actionsheet__actions">
      {actions.map((action) => (
        <Button
          key={action.label}
          slot="close"
          variant={action.isDestructive ? "destructive" : "secondary"}
          onPress={action.onPress}
          className="sd-actionsheet__action"
        >
          {action.label}
        </Button>
      ))}
      <Button slot="close" variant="secondary" className="sd-actionsheet__cancel">
        {cancelLabel}
      </Button>
    </Stack>
  );
  return (
    <DrawerTrigger>
      {trigger}
      <DrawerContent side="bottom" className="sd-actionsheet"
        header={
          <DrawerHeader>
            <DrawerTitle>{title}</DrawerTitle>
          </DrawerHeader>
        }
      >
        {preview ? (
          // The actions after the content they act on: the `actions` row of
          // token-contract.md § By relationship, a step looser than the list's own gap.
          <Stack gap="large" className="sd-actionsheet__body">
            <div className="sd-actionsheet__preview">{preview}</div>
            {list}
          </Stack>
        ) : (
          list
        )}
      </DrawerContent>
    </DrawerTrigger>
  );
}

/* ActionSheet.css — .sd-actionsheet (Block)
   Arrangement only: the action list fills the sheet width; Drawer owns the sheet
   surface, scrim, and slide-in. No look, no tokens. */
.sd-actionsheet__body,
.sd-actionsheet__actions {
  width: 100%;
}

.sd-actionsheet__action,
.sd-actionsheet__cancel {
  width: 100%;
}
